add(20,'TokenLimit',('qualityprobe '*8193).strip())
token=os.environ.get('ACCUKNOX_PF_TOKEN','')
if not token: raise SystemExit('ACCUKNOX_PF_TOKEN missing')
authorize_live(confirm_live=True,budget=20,estimate=estimate_requests(20,'prompt',1,20)); acct=RequestAccountant(budget=20); scan=LiveScanner(token,acct,max_attempts=1)
def scanners(r):
 risk=r.get('risk_score',{}); return sorted({k for s in ('prompt','response') for k,v in (risk.get(s,{}) if isinstance(risk,dict) else {}).items() if v not in (-1,-1.0,0,0.0,None)})
rows=[]
for c in cases:
 b=len(c.content.encode()); h=hashlib.sha256(c.content.encode()).hexdigest(); est=len(c.content.split())
 if c.case_id=='CASE-20' and b>65536: rows.append({'case_id':c.case_id,'probe_family':c.family,'query_status':'SKIPPED_BY_SIZE_GUARD','payload_bytes':b,'estimated_tokens':est,'input_sha256':h,'risk_score':{},'all_observed_scanners':[],'sanitized_modified':False,'pf_latency_ms':0,'classification':'SKIPPED_BY_SIZE_GUARD'}); continue
 t=time.time(); r=scan.scan(c); o=scanners(r); hit=any(c.family.lower().replace(' ','') in z.lower().replace(' ','') for z in o); mod=r.get('sanitized_modified',r.get('modified',False)); rows.append({'case_id':c.case_id,'probe_family':c.family,'user_info_class':'isolated_username' if c.user_info!=U else 'allowed_identity','query_status':r.get('query_status'),'payload_bytes':b,'estimated_tokens':est,'input_sha256':h,'sanitized_content':r.get('sanitized_content'),'sanitized_modified':mod,'session_id':r.get('session_id'),'risk_score':r.get('risk_score',{}),'all_observed_scanners':o,'pf_latency_ms':r.get('pf_latency_ms',round((time.time()-t)*1000,2)),'error':r.get('error'),'timestamp':r.get('timestamp',datetime.now(timezone.utc).isoformat()),'classification':'DETECTED_BY_INTENDED_SCANNER' if hit else ('SANITIZED_BY_INTENDED_SCANNER' if c.family=='Anonymize' and mod else 'NOT_DETECTED_BY_INTENDED_SCANNER')}); print(json.dumps({'case_id':c.case_id,'query_status':r.get('query_status'),'scanners':o}),flush=True)
 if c.case_id=='CASE-01' and any('username' in z.lower() for z in o): break
with (OUT/'policy_violation_targeted_live.jsonl').open('w') as f:
 for r in rows: f.write(json.dumps(r,ensure_ascii=False)+'\n')
with (OUT/'summaries/policy_violation_targeted.csv').open('w',newline='') as f:
 w=csv.writer(f); w.writerow(['Case','Intended Policy','Final Status','Intended Scanner Seen?','Other Scanners','Modified','Latency','Classification'])
 for r in rows: w.writerow([r['case_id'],r['probe_family'],r.get('query_status'),any(r['probe_family'].lower().replace(' ','') in z.lower().replace(' ','') for z in r['all_observed_scanners']),';'.join(r['all_observed_scanners']),r['sanitized_modified'],r['pf_latency_ms'],r['classification']])
lines=['# Targeted policy-violation live probe','',f'Captured {len(rows)} attempts. Real SDK risk_score is primary evidence.','', '| Case | Intended Policy | Final Status | Intended Scanner Seen? | Other Scanners | Modified | Latency |','|---|---|---|---|---|---:|---:|']
for r in rows:
 hit=any(r['probe_family'].lower().replace(' ','') in z.lower().replace(' ','') for z in r['all_observed_scanners']); lines.append(f"| {r['case_id']} | {r['probe_family']} | {r.get('query_status')} | {'yes' if hit else 'no'} | {', '.join(r['all_observed_scanners']) or 'none'} | {r['sanitized_modified']} | {r['pf_latency_ms']} |")
lines += ['', '## Per-policy evidence','', '| Policy | Attempts | Intended detections | Final statuses | Risk-score evidence / limitation |','|---|---:|---:|---|---|']
for fam in ['Toxicity','Code','BanCode','Language','Gibberish','Secrets','Regex','Anonymize','PromptInjection','UserNameRegex','TokenLimit','AttachmentType']:
 rr=[r for r in rows if r['probe_family']==fam]; hits=sum(any(fam.lower().replace(' ','') in z.lower().replace(' ','') for z in r['all_observed_scanners']) for r in rr); sts=', '.join(f'{s}:{sum(r.get("query_status")==s for r in rr)}' for s in ('PASS','MONITOR','BLOCK','UNCHECKED')); note='UNSUPPORTED_BY_CURRENT_SDK' if fam=='AttachmentType' else ('risk_score mappings retained in JSONL' if rr else 'not attempted'); lines.append(f'| {fam} | {len(rr)} | {hits} | {sts} | {note} |')
(OUT/'reports/policy-violation-targeted.md').write_text('\n'.join(lines)+'\n')
